int data[] = {10, 20, 30, 40};
const size_t INT_SIZE = sizeof(int); // Example: 4 bytes

// Standard Scaling (Compiler handles INT_SIZE)
int* p_base = data;
int val_std = *(p_base + 2); // Accesses 30 (Moves 2 * 4 bytes)

// Manual Byte-Level Traversal (No compiler scaling)
char* p_byte = (char*)data;

// Scaling for Index 3: 3 * INT_SIZE bytes
const int index = 3;
size_t byte_offset = index * INT_SIZE;

// Scaling Optimization (If INT_SIZE == 4, replace * 4 with << 2)
// size_t byte_offset_opt = index << 2;

int* p_manual = (int*)(p_byte + byte_offset);
int val_manual = *p_manual; // Accesses 40
